'use strict';

/**
 * #833: the OSDM response schemas the simulator's answers are checked against
 * (OSDM_Simulator/tests/fixtures/osdm-response-schemas.json) are generated by
 * scripts/generate-osdm-response-schemas.js; its 3.8 is the repository's.
 */

const fs = require('node:fs');
const path = require('node:path');
const yaml = require('js-yaml');
const G = require('../../scripts/generate-osdm-response-schemas');

const REPO = path.join(__dirname, '..', '..', '..');
const generated = JSON.parse(fs.readFileSync(path.join(REPO, 'OSDM_Simulator', 'tests', 'fixtures', 'osdm-response-schemas.json'), 'utf8'));

describe('#833 the simulator\'s response schemas', () => {
  test('they hold the versions of the simulator\'s providers, and the 3.8 to 3.12 are the repository\'s specifications', () => {
    expect(Object.keys(generated.versions)).toEqual(['3.6.0', '3.7.0', '3.8.0', '3.9.0', '3.10.0', '3.11.0', '3.12.0']);
    for (const v of ['3.8.0', '3.9.0', '3.10.0', '3.11.0', '3.12.0']) {
      const spec = yaml.load(fs.readFileSync(path.join(REPO, 'Documentation', 'Test_Coverage', 'OSDM_reference', `OSDM-online-api-v${v}.yml`), 'utf8'));
      expect(generated.versions[v]).toEqual(JSON.parse(JSON.stringify(G.forVersion(spec))));
    }
  });

  test('every provider of the simulator has a version the file holds', () => {
    for (const file of ['alpha', 'beta', 'gamma']) {
      const provider = JSON.parse(fs.readFileSync(path.join(REPO, 'OSDM_Simulator', 'providers', `${file}.json`), 'utf8'));
      expect(Object.keys(generated.versions)).toContain(provider.osdmVersion);
    }
  });

  test('the versions differ where OSDM does: documents are named in 3.8 only, inboundTripCoverage exists from 3.7', () => {
    const members = (v, name) => Object.keys(generated.versions[v].schemas[name].properties || {});
    expect(members('3.8.0', 'Fulfillment')).toContain('fulfillmentDocumentRefs');
    expect(members('3.7.0', 'Fulfillment')).not.toContain('fulfillmentDocumentRefs');
    expect(members('3.7.0', 'BookedOffer')).toContain('inboundTripCoverage');
    expect(members('3.6.0', 'BookedOffer')).not.toContain('inboundTripCoverage');
  });

  test('a response given through components.responses is read; one with no JSON body is not', () => {
    const spec = { components: { responses: { R: { content: { 'application/problem+json': { schema: { $ref: '#/components/schemas/Problem' } } } } } } };
    expect(G.responseSchema(spec, { $ref: '#/components/responses/R' })).toEqual({ $ref: '#/components/schemas/Problem' });
    expect(G.responseSchema(spec, { description: 'no content' })).toBeNull();
  });
});
